<?php $this->layout('default'); use Moves\Services\CmsAudit; use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling; use Moves\Services\PlatformDirectory as D; use Moves\Support\CmsView as V;
$u = D::user($id); if ($u === null) { http_response_code(404); echo V::empty('Usuário não encontrado.'); return; }
$subs = CmsAuth::can($admin, 'subscriptions.view') ? PlatformBilling::subscriptions(['user_id' => $id], 1)['rows'] : []; ?>
<div class="cms-alert cms-alert-info">Esta tela não mostra dados financeiros privados do cliente.</div>
<div class="cms-grid-2"><div><div class="cms-card"><h2><?= V::e(trim($u['first_name'] . ' ' . $u['last_name'])) ?></h2><dl class="cms-dl"><dt>E-mail</dt><dd><?= V::e($u['email']) ?></dd><dt>Situação</dt><dd><?= V::badge($u['status'], D::USER_STATUS[$u['status']] ?? $u['status']) ?></dd><dt>Cadastro</dt><dd><?= V::date($u['created_at']) ?></dd></dl></div>
<div class="cms-card"><h2>Empresas vinculadas</h2><?php $cs = D::userCompanies($id); if ($cs === []): ?><?= V::empty('Sem empresas.') ?><?php else: foreach ($cs as $c): ?><p><?= CmsAuth::can($admin, 'companies.view') ? '<a href="/empresas/' . (int) $c['id'] . '">' . V::e($c['name']) . '</a>' : V::e($c['name']) ?> · <?= V::e($c['role_name']) ?></p><?php endforeach; endif; ?></div>
<div class="cms-card"><h2>Plano e assinatura</h2><?php if ($subs === []): ?><?= V::empty('Sem assinatura registrada.') ?><?php else: foreach ($subs as $s): ?><p><a href="/assinaturas/<?= (int) $s['id'] ?>"><?= V::e($s['plan_name']) ?></a> · <?= V::badge($s['status'], V::SUB_STATUS[$s['status']] ?? $s['status']) ?></p><?php endforeach; endif; ?></div>
<?php if (CmsAuth::can($admin, 'audit.view')): ?><div class="cms-card"><h2>Histórico administrativo</h2><?php $logs = CmsAudit::listing(['type' => 'user', 'resource_id' => (string) $id], 1, 15)['rows']; if ($logs === []): ?><?= V::empty('Sem registros.') ?><?php else: foreach ($logs as $l): ?><p><small><?= V::date($l['created_at']) ?> · <?= V::e($l['event_type']) ?> · <?= V::e($l['actor_email'] ?? 'Sistema') ?></small></p><?php endforeach; endif; ?></div><?php endif; ?></div>
<aside><?php if (CmsAuth::can($admin, 'users.manage')): ?><form class="cms-card" method="post" action="/acao/user-suspend" data-confirm="Confirmar a alteração de acesso deste usuário?"><h2><?= $u['status'] === 'suspended' ? 'Reativar conta' : 'Suspender conta' ?></h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><input type="hidden" name="suspend" value="<?= $u['status'] === 'suspended' ? 0 : 1 ?>"><?= V::field('Motivo', 'reason', '', ['type' => 'textarea', 'rows' => 2, 'help' => 'A suspensão encerra as sessões abertas do usuário.']) ?><button class="<?= $u['status'] === 'suspended' ? 'cms-btn' : 'cms-btn-danger' ?>"><?= $u['status'] === 'suspended' ? 'Reativar' : 'Suspender' ?></button></form><?php endif; ?></aside></div>
